import os
import random
import numpy as np
import torch


class Config:
    """
    Configuration module for the Flow-Aligned Pyramid Siamese Network.
    Defines project-wide constants, paths, and hyperparameters.
    """

    # =========================================================================
    # Paths
    # =========================================================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata files (generated by the provided script)
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Working directory for caching and outputs
    # Specified in requirements: ./working/idea_12/
    WORKING_DIR = "./working/idea_12"
    CACHE_DIR = WORKING_DIR
    CHECKPOINT_DIR = os.path.join(WORKING_DIR, "checkpoints")

    # Submission output
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # =========================================================================
    # Data Hyperparameters
    # =========================================================================
    # Input resolution for the Siamese Network
    IMG_SIZE = (768, 768)

    # Compute settings
    NUM_WORKERS = 12  # Utilizing available vCPUs

    # =========================================================================
    # Model Hyperparameters
    # =========================================================================
    BACKBONE = "efficientnet_b2"

    # Loss weighting for class imbalance (1:47 ratio)
    POS_WEIGHT = 47.0

    # =========================================================================
    # Training Hyperparameters
    # =========================================================================
    # Batch size adjusted for A100 40GB + 768x768 Siamese inputs
    BATCH_SIZE = 16

    LEARNING_RATE = 1e-4
    NUM_EPOCHS = 10

    # Random seed for reproducibility
    SEED = 42

    # =========================================================================
    # Debugging / Development
    # =========================================================================
    # Flags to control dataset size for rapid iteration
    DEBUG = False
    DEBUG_DATA_SIZE = 500  # Number of samples to use when DEBUG is True

    @classmethod
    def setup(cls):
        """
        Initializes the environment by creating necessary directories
        and setting random seeds for reproducibility.
        """
        # Create directories
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.CHECKPOINT_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)

        # Set seeds
        cls.set_seed(cls.SEED)

    @staticmethod
    def set_seed(seed):
        """
        Sets fixed random seeds for python, numpy, and torch.
        """
        random.seed(seed)
        np.random.seed(seed)
        torch.manual_seed(seed)
        if torch.cuda.is_available():
            torch.cuda.manual_seed(seed)
            torch.cuda.manual_seed_all(seed)

        # Ensure deterministic behavior
        torch.backends.cudnn.deterministic = True
        torch.backends.cudnn.benchmark = False
